use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let a:Vec<_>=std::env::args().collect();let root=Path::new(&a[1]);assert!(!root.exists());fs::create_dir(root).unwrap();let setup=fs::canonicalize(".").unwrap();let bin=std::env::current_exe().unwrap().with_file_name("calibration631");let mut supported=0;let mut first=None;for i in 0..4{for j in i+1..4{let name=format!("anchors{i}{j}");let status=Command::new(&bin).arg(root.join(&name)).env("HEC_SETUP_DIR",&setup).env("HEC_ANCHOR_I",i.to_string()).env("HEC_ANCHOR_J",j.to_string()).stdout(Stdio::from(fs::File::create(root.join(format!("{name}.stdout"))).unwrap())).stderr(Stdio::from(fs::File::create(root.join(format!("{name}.stderr"))).unwrap())).status().unwrap();fs::write(root.join(format!("{name}.status")),format!("exit={:?}\n",status.code())).unwrap();if status.success(){supported+=1;if first.is_none(){first=Some(name.clone());}println!("SUPPORTED case={name}");}else{let e=fs::read_to_string(root.join(format!("{name}.stderr"))).unwrap();assert!(status.code()==Some(101)&&(e.contains("empty_registered_fiber")||e.contains("no_supported_calibration")),"unexpected_calibration_failure {name}");println!("UNSUPPORTED case={name}");}}}fs::write(root.join("SELECTED.txt"),first.clone().unwrap_or_else(||"NONE".into())+"\n").unwrap();println!("COHORT_COMPLETE requested=6 supported={supported} selected={first:?} actual_alignment_or_DLP_verified=false");}
